package io.aetheris.orchestrator.trading;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class BacktestService {private final BacktestResultRepository repository;public BacktestService(BacktestResultRepository repository){this.repository=repository;}public BacktestResultEntity run(BacktestRequest r){if(r.symbol()==null||r.symbol().isBlank()||r.bars().size()<30)throw new IllegalArgumentException("symbol and at least 30 bars are required");int fast=Math.max(2,r.fastWindow()),slow=Math.max(fast+1,r.slowWindow());if(slow>=r.bars().size()/2)throw new IllegalArgumentException("slowWindow is too large");double frac=r.trainFraction()<=.5||r.trainFraction()>=.9?.7:r.trainFraction();int split=Math.max(slow+2,(int)Math.floor(r.bars().size()*frac));double initial=r.initialBalance()>0?r.initialBalance():10000;Metrics train=simulate(r.bars().subList(0,split),fast,slow,initial);Metrics test=simulate(r.bars().subList(Math.max(0,split-slow),r.bars().size()),fast,slow,initial);int trades=train.trades+test.trades,wins=train.wins+test.wins;double winRate=trades==0?0:(double)wins/trades*100;return repository.save(new BacktestResultEntity(UUID.randomUUID(),r.symbol().trim().toUpperCase(Locale.ROOT),r.bars().size(),trades,train.returnPct,test.returnPct,winRate,Math.max(train.maxDrawdownPct,test.maxDrawdownPct),initial*(1+test.returnPct/100)));}public List<BacktestResultEntity> recent(){return repository.findTop100ByOrderByCreatedAtDesc();}private Metrics simulate(List<MarketBar> bars,int fast,int slow,double initial){double balance=initial,peak=initial,maxDd=0;int position=0,trades=0,wins=0;double entry=0;for(int i=slow;i<bars.size();i++){double f=avg(bars,i-fast,i),s=avg(bars,i-slow,i);int signal=f>s?1:f<s?-1:0;double price=bars.get(i).close();if(position!=0&&signal!=position){double ret=(price-entry)/entry*position;double pnl=balance*ret;balance+=pnl;trades++;if(pnl>0)wins++;position=0;}if(position==0&&signal!=0){position=signal;entry=price;}peak=Math.max(peak,balance);if(peak>0)maxDd=Math.max(maxDd,(peak-balance)/peak*100);}if(position!=0){double price=bars.getLast().close();double pnl=balance*((price-entry)/entry*position);balance+=pnl;trades++;if(pnl>0)wins++;}return new Metrics((balance-initial)/initial*100,maxDd,trades,wins);}private double avg(List<MarketBar>b,int from,int to){double s=0;for(int i=from;i<to;i++)s+=b.get(i).close();return s/(to-from);}private record Metrics(double returnPct,double maxDrawdownPct,int trades,int wins){}
}
